#pragma once

#include "base.hpp"

namespace epi::presets {

/**
 * Invert (Minimal 3.5D): a Web of Circles in a Mirror Box.
 *
 * Mathematics:
 * - The Torus reduction is the triangle wave, which is reflection in the
 *   lines x = +-1 and y = +-1 (and their translates). The inner function
 *   1/z is inversion in the unit circle followed by reflection in the real
 *   axis, and the box is symmetric under that reflection. Every pass
 *   therefore applies one element of the group generated by reflections in
 *   four lines, one circle and the real axis: a Kleinian reflection group.
 * - The unit circle touches all four lines, at +-1 and +-i. Each touching
 *   point is a parabolic cusp. Inside the box and outside the circle lie
 *   four corner pieces, each a triangle with angles pi/2, 0, 0.
 * - On a corner piece 1/z lands inside the disc, where the fold does
 *   nothing, and 1/(1/z) = z: every corner point has period 2. Every other
 *   point is carried onto a corner piece in finitely many passes.
 *
 * Pipeline: Invert with bare slots (zn0 = zn2 = 1) and Torus. The Cross seed
 * draws the two axes, which are mirror lines of the configuration; the
 * group carries them into circles and lines, so the picture is the orbit
 * of the axes: a web of circles, nested ever smaller into the four cusps.
 * OKLab hue step 1/8 colours each nesting depth. After a few dozen passes
 * the image is stationary; only the hue drifts.
 *
 * Fidelity:   identity (1/z exactly, the shader's own fold)
 * Cell:       Invert / Torus / Cross / OKLabColorRotation
 * Nearest:    schottky_kleinian_limit_necklace uses the same pair with
 *             generic slots, so nothing is tangent and the limit set is
 *             dust; spatial_wave_mobius_horocycle_bouquet is one parabolic
 *             Mobius map. Here every mirror meets the circle tangentially.
 * Height:     age = passes; a tile's depth is its passes to a corner piece.
 * Hue clock:  bounded; step 1/8 +- 0.01.
 * Fastest lane: 0.02 Hz
 * Status:     designed from source on 2026-11-16. In double precision on a
 *             400 x 400 grid, 100 % of points were on a 2-cycle within 400
 *             passes (median landing 1 pass, 90 % within 4). Exponent over
 *             64 passes: median 0.008, none below -0.01. A numpy model of
 *             the pass (nearest sampling, HSV for OKLab) was drawn to check
 *             composition. Not built, rendered by the engine or measured.
 * @assert p_X == 0 && p_C <= 0.05
 */
inline Pattern invert_minimal_ford_mirror_box_circle_web() {
  Pattern p;
  p.name = "invert_minimal_ford_mirror_box_circle_web";
  p.inner = InnerFunction::Invert;
  p.reduction = ReductionType::Torus;
  p.zn.zn[0] = {1.0f, 0.0f};
  p.zn.zn[1] = {0.0f, 0.0f};
  p.zn.zn[2] = {1.0f, 0.0f}; // circle of radius 1: tangent to all four mirrors
  p.zn.zn[3] = {0.0f, 0.0f};

  p.color.hue_rotation = 0.125f;
  p.color.sat_scale = 1.0f;
  p.color.fade = 0.95f;
  p.color.color_mode = as_int(ColorMode::OKLabColorRotation);
  p.color.spiral_angle_coeff = 0.0f;
  p.color.spiral_radius_coeff = 0.0f;
  p.color.chroma_breath_amp = 0.05f;
  p.color.chroma_breath_freq = 0.1f;
  p.color.chroma_breath_phase = 0.0f;
  p.color.hue_velocity_base = 0.0f;
  p.color.hue_velocity_breath = 0.0006f;
  p.color.hue_velocity_drift = 0.0002f;
  p.color.luma_shape_depth = 0.0f;
  p.color.luma_shape_center = 0.0f;

  p.seed.type = SeedType::Cross;
  p.seed.border_width = 0.05f;
  p.seed.hue = 0.52f;
  p.seed.hue_speed = 0.02f;
  p.seed.alpha = 1.0f;
  p.seed.pulse_freq = 0.05f;
  p.seed.pulse_amp = 0.0f;
  p.speed = 0.8f;

  p.motion
      .add("depth_hue_drift",
           control::ModLane{.wave = control::Waveform::Sine,
                            .frequency_hz = 0.007f,
                            .amplitude = 0.01f,
                            .offset = 0.125f},
           control::ModTarget::HueRot)
      .add("relief_depth",
           control::ModLane{.wave = control::Waveform::Triangle,
                            .frequency_hz = 0.02f,
                            .amplitude = 0.025f,
                            .offset = 0.05f},
           control::ModTarget::ChromaBreathAmp);

  return p;
}

} // namespace epi::presets
